import hashlib,json,math
from pathlib import Path
import numpy as np
from multi_robot_exploration import control as c
root=Path('log/p3b5/p3b5_v91_dev_fixed_ap/p3b5_v91_dev_fixed_lab202_lab_far_northwest_3r_seed202_ap');p=root/'snapshots.jsonl';frames=[json.loads(l) for l in p.open()];out=dict(scope='Read-only delivered AP conditional geometry, not original coordinator buffers or causal mission replay. Native truth does not enter replay/control.',snapshot_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),source=Path(__file__).read_text(),frames=[])
def yaw(q):return math.atan2(2*(q['w']*q['z']+q['x']*q['y']),1-2*(q['y']**2+q['z']**2))
for frame in frames[-3:]:
 m=frame['messages'];grid=m['map'];info=grid['info'];res=info['resolution'];origin=(info['origin']['position']['x'],info['origin']['position']['y']);raw=np.array(grid['data'],dtype=np.int16).reshape(info['height'],info['width']);positions={};states={}
 for robot in ('tb1','tb2','tb3'):
  odom=m[robot+'/odom']['pose']['pose'];transforms=m[robot+'/tf']['transforms'];tf=next(t['transform'] for t in transforms if t['header']['frame_id'].lstrip('/').endswith('map') and t['child_frame_id'].lstrip('/').endswith('odom'));a=yaw(tf['rotation']);x=odom['position']['x'];y=odom['position']['y'];positions[robot]=(tf['translation']['x']+math.cos(a)*x-math.sin(a)*y,tf['translation']['y']+math.sin(a)*x+math.cos(a)*y);states[robot]=json.loads(m[robot+'/battery_state']['data'])
 target_data=json.loads(m['target_detection']['data']);target=(target_data['target_x'],target_data['target_y']);planning,cells=c.planning_grid_without_self_returns(raw,res,origin,positions);item=dict(observer_time=frame['observer_time'],positions=positions,target=target,observer=target_data['robot'],source_time=target_data['_gateway']['source_time'],self_return_cells=cells)
 for kind,grid in (('raw',raw),('conditional_planning_copy',planning)):
  safe=c.traversable_grid(grid,res,c.RALLY_PATH_CLEARANCE_M);candidates=c.rally_pose_candidates(grid,res,origin,target);routes={}
  for robot,pos in positions.items():
   start=c.world_to_grid(*pos,res,*origin);escaped,escape=c.navigation_start_route(grid,safe,start,max(1,math.ceil(.6/res)));distances=c.path_distance_grid(safe,escaped);home=(float(states[robot]['charge_x']),float(states[robot]['charge_y']));home_cell=c.world_to_grid(*home,res,*origin);home_start,home_escape=c.navigation_start_route(grid,safe,home_cell,max(1,math.ceil(.6/res)));home_distances=c.path_distance_grid(safe,home_start)
   routes[robot]=dict(start_cell=start,raw_start=int(grid[start]) if 0<=start[0]<grid.shape[0] and 0<=start[1]<grid.shape[1] else None,escaped_start=escaped,home_cell=home_cell,raw_home=int(grid[home_cell]),escaped_home=home_start,reachable_candidates=sum(np.isfinite(distances[c.world_to_grid(q.x,q.y,res,*origin)]) for q in candidates),home_reachable_candidates=sum(np.isfinite(home_distances[c.world_to_grid(q.x,q.y,res,*origin)]) for q in candidates))
  no_battery=c.assign_rally_poses(grid,res,origin,positions,target);battery=c.assign_rally_poses(grid,res,origin,positions,target,battery_states=states,observer_robot=target_data['robot'],current_positions=positions)
  item[kind]=dict(candidate_count=len(candidates),routes=routes,unfunded_assignment_count=len(no_battery),battery_assignment_count=len(battery),assignment={n:vars(q) for n,q in battery.items()})
 out['frames'].append(item);print(json.dumps(item,default=lambda v:int(v) if isinstance(v,np.integer) else float(v)),flush=True)
p=Path('/tmp/p3b5_v91_found_assignment_diagnosis.json');assert not p.exists();p.write_text(json.dumps(out,indent=2,default=lambda v:int(v) if isinstance(v,np.integer) else float(v))+'\n')
